692:     pub(super) fn fact_strike_segments(
693:         &mut self,
694:         target: UnitInstanceId,
695:         count: usize,
696:         positive: bool,
697:     ) -> Result<(StrikeOrdinal, u32, bool, bool), GameError> {
698:         crate::authoring::control::charge(count as u64, "strike_segments")?;
699:         let existing = self
700:             .runtime_strike_scope
701:             .as_ref()
702:             .and_then(|scope| scope.targets.get(&target))
703:             .copied();
704:         let mut progress = match existing {
705:             Some(value) => value,
706:             None => {
707:                 if self.runtime_strike_scope.is_some() {
708:                     self.runtime_facts.reserve_fact_storage(Some(128))?;
709:                 }
710:                 StrikeProgress {
711:                     ordinal: self.runtime_facts.strike()?,
712:                     next_segment: 0,
713:                     mutations: 0,
714:                     positive: false,
715:                 }
716:             }
717:         };
718:         let next = progress.next_segment.checked_add(count);
719:         control::limit(
720:             Code::StrikeSegmentLimit,
721:             "strike_segments",
722:             self.runtime_facts.limits.max_strike_segments,
723:             next,
724:         )?;
725:         let result = (
726:             progress.ordinal,
727:             progress.next_segment as u32,
728:             progress.mutations == 0,
729:             positive && !progress.positive,
730:         );
731:         progress.next_segment = next.expect("admitted segments");
732:         progress.mutations = progress
733:             .mutations
734:             .checked_add(1)
735:             .ok_or_else(|| overflow("strike_mutations"))?;
736:         progress.positive |= positive;
737:         if let Some(scope) = &mut self.runtime_strike_scope {
738:             scope.targets.insert(target, progress);
739:         }
740:         Ok(result)

